fn ensure_prioritary_property(
    &mut self,
    context: &mut computed::Context,
    decls: &Declarations,
    cache: &mut ShorthandsWithPropertyReferencesCache,
    attribute_tracker: &mut AttributeTracker,
    id: PrioritaryPropertyId,
) {
    if self.ensured_prioritary.contains(id) {
        return;
    }
    self.ensured_prioritary.insert(id);
    let deps = id.dependencies();
    if !self.ensured_prioritary.contains_all(deps) {
        for dep in deps.iter() {
            self.ensure_prioritary_property(context, decls, cache, attribute_tracker, dep);
        }
    }
    self.apply_one_prioritary_property(context, decls, cache, id, attribute_tracker);
}

/// Cascade a given custom property declaration.

    fn apply_prepared_priority(
        &mut self,
        longhand: LonghandId,
        attribute_tracker: &mut AttributeTracker,
    ) {
        let id = PrioritaryPropertyId::from_longhand(longhand).unwrap();
        self.cascade.ensured_prioritary.insert(id);
        for dependency in id.dependencies().iter() {
            self.cascade.ensure_prioritary_property(
                self.computed_context,
                self.decls,
                self.cache,
                attribute_tracker,
                dependency,
            );
        }
        let prepared = self.prepared_priorities.remove(&longhand).unwrap();
        for (declaration, priority) in prepared {
            debug_assert!(self.cascade.longhand_is_eligible(
                self.computed_context.included_cascade_flags,
                longhand,
                priority
            ));
            self.cascade.apply_prepared_longhand(
                self.computed_context,
                longhand,
                declaration,
                priority,
            );
            if self.cascade.seen.longhands.contains(longhand) {
                self.cascade
                    .did_apply_prioritary_property(self.computed_context, id);
                break;
            }
        }
    }
}

